/********************************************** 
 * 함수명   : fn_GetParIsurCd
 * 설명       : 발행기관 팝업에 넘길 데이터를 정의한다.
 ***********************************************/
scwin.getParIsurCd = function(arrPar) {
    scwin.arrPar[0] = {
        ISUR_CD: vSelObj.getValue(),
        CORP_NM: vSelObj.getValue()
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    scwin.arrPar, length;
};

/********************************************** 
 * 함수명   : fn_SetParIsurCd
 * 설명       : 발행기관 팝업에서 받은 데이터를 설정한다.
 ***********************************************/
scwin.setParIsurCd = function(arrPar) {
    if (vsCoPopGb === "SCH") {
        txb_COM_NM.setValue(scwin.arrPar[0].CORP_NM);
        txb_ISUR_CD.setValue(scwin.arrPar[0].ISUR_CD);
    } else {
        const cbdata = "^ ," + scwin.arrPar[0].ISUR_CD + "^" + scwin.arrPar[0].CORP_NM;
        vSelObj.CBData = cbdata;
        vSelObj.setValue(scwin.arrPar[0].ISUR_CD);
    }
};

/********************************************** 
 * 함수명   : fn_ShowIsur
 * 설명       : 발행기관 팝업을 보여준다.
 ***********************************************/
scwin.showIsur = function(selObj) {
    if (vsCoPopGb !== "SCH") {
        if (vRowCount === 0) return;
    }
    vSelObj = selObj;
    fn_GetPar = fn_GetParIsurCd;
    fn_SetPar = fn_SetParIsurCd;
    $c.bns.fn_PopIsurSearch(selObj);
};

/********************************************** 
 * 함수명   : ins_search
 * 설명       : 일자별  표준코드 조회 
 ***********************************************/
scwin.ins_search = async function() {
    $c.cm.setColumnProp(grd_Grid, "CHK", "headcheck", false);
    let STD_CD_APPL_CONTN_TP_CD = "";
    // alert('getObjectValue(ckb_STD_CD_APPL_CONTN_TP_CD_01)'+getObjectValue(ckb_STD_CD_APPL_CONTN_TP_CD_01));
    if (ckb_STD_CD_APPL_CONTN_TP_CD_01.getValue() === 'Y') STD_CD_APPL_CONTN_TP_CD += '01,';
    if (ckb_STD_CD_APPL_CONTN_TP_CD_02.getValue() === 'Y') STD_CD_APPL_CONTN_TP_CD += '02,';
    if (ckb_STD_CD_APPL_CONTN_TP_CD_11.getValue() === 'Y') STD_CD_APPL_CONTN_TP_CD += '11,';
    if (ckb_STD_CD_APPL_CONTN_TP_CD_10.getValue() === 'Y') STD_CD_APPL_CONTN_TP_CD += '10,';
    if (ckb_STD_CD_APPL_CONTN_TP_CD_12.getValue() === 'Y') STD_CD_APPL_CONTN_TP_CD += '12,';
    if (ckb_STD_CD_APPL_CONTN_TP_CD_04_05.getValue() === 'Y') STD_CD_APPL_CONTN_TP_CD += '04,05,';
    if (ckb_STD_CD_APPL_CONTN_TP_CD_06.getValue() === 'Y') STD_CD_APPL_CONTN_TP_CD += '06,';
    if (ckb_STD_CD_APPL_CONTN_TP_CD_07.getValue() === 'Y') STD_CD_APPL_CONTN_TP_CD += '07,';
    if (ckb_STD_CD_APPL_CONTN_TP_CD_03.getValue() === 'Y') STD_CD_APPL_CONTN_TP_CD += '03,';
    if (ckb_STD_CD_APPL_CONTN_TP_CD_09.getValue() === 'Y') STD_CD_APPL_CONTN_TP_CD += '09,';
    if (ckb_STD_CD_APPL_CONTN_TP_CD_13.getValue() === 'Y') STD_CD_APPL_CONTN_TP_CD += '13,';
    if (ckb_STD_CD_APPL_CONTN_TP_CD_08.getValue() === 'Y') STD_CD_APPL_CONTN_TP_CD += '08,';
    if (ckb_ALL.getValue() === ' Y') STD_CD_APPL_CONTN_TP_CD = '';

    // 코드부여일, 입금일 입력안됨
    if ((edt_SSTD_CD_GRNT_DD.getValue() === "" || edt_ESTD_CD_GRNT_DD.getValue() === "") &&
        (edt_SFEE_DEPO_DD.getValue() === "" || edt_EFEE_DEPO_DD.getValue() === "")) {
        alert(" 코드부여일 또는 입금일을 3년 이내로 입력해야 합니다.");
        edt_SSTD_CD_GRNT_DD.focus();
        return false;
    } else {
        // 코드부여일 또는 입금일 입력되었다.
        // 3년 이내 체크.
        if ((edt_SSTD_CD_GRNT_DD.getValue() !== "" && edt_ESTD_CD_GRNT_DD.getValue() !== "") &&
            eval($c.utils.cGetPlusYear(edt_SSTD_CD_GRNT_DD.getValue(), 3)) < eval(edt_ESTD_CD_GRNT_DD.getValue())) {
            alert("코드부여일의 검색 기간은 3년 이내로만 가능합니다.");
            edt_SSTD_CD_GRNT_DD.focus();
            return false;
        }
        if ((edt_SFEE_DEPO_DD.getValue() !== "" && edt_EFEE_DEPO_DD.getValue() !== "") &&
            eval($c.utils.cGetPlusYear(edt_SFEE_DEPO_DD.getValue(), 3)) < eval(edt_EFEE_DEPO_DD.getValue())) {
            alert("입금일의 검색 기간은 3년 이내로만 가능합니다.");
            edt_SFEE_DEPO_DD.focus();
            return false;
        }
    }

    // 코드부여일 순서 체크
    if ($c.stf.compareFromToDate2(edt_SSTD_CD_GRNT_DD, edt_ESTD_CD_GRNT_DD) === false) {
        return false;
    }
    // 입금일 순서 체크
    if ($c.stf.compareFromToDate2(edt_SFEE_DEPO_DD, edt_EFEE_DEPO_DD) === false) {
        return false;
    }
    const sbmOptions = {
        id : "sbm_dts_List",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_List=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    scwin.dts_List_OnLoadCompleted(dts_List.getRowCount()); // 구 콜백 연결

};

// sap 전송
scwin.ins_send = async function() {
    // 사전체크
    if (!scwin.chkValid("ins_Trans")) {
        return;
    }

    // alert(dts_List.CountRow);
    // for( var nRow = 1; nRow <= dts_List.CountRow; nRow++ ){
    //	alert(dts_List.NameValue(nRow, "CHK"));
    // }

    const msg = $c.stf.getMessageParam("MSG-A006", "일괄수익처리");
    const res = window.confirm(msg);
    if (res) {
        // 선택된 Row만 서버로 전송..
        scwin.setTransData();
        trs_Return.KeyName = "toinb_dataid4";

        // [전환검토] trs_Return.Parameters → 동적 파라미터(필요 시 sbmOptions 에 반영)
        // const sbmParams = {
        //     EMP_NO : js_emp_no,
        //     EMP_NM : js_emp_nm,
        //     EMAIL : js_email
        // };
        const sbmOptions = {
            id : "sbm_trs_Return",
            action : "/PrepayInfoAction.do",
            ref : "dts_List",
            target : "trs_Return=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    }
};

/**
 * 사전체크
 */
scwin.chkValid = function(pGubun) {
    if (pGubun === "ins_search") {
        if (edt_FROM_TRNSM_DD.getValue() === "") {
            alert("검색 시작일을 입력하세요.");
            edt_FROM_TRNSM_DD.Focus();
            return false;
        }
        if (edt_TO_TRNSM_DD.getValue() === "") {
            alert("검색 종료일을 입력하세요.");
            edt_TO_TRNSM_DD.Focus();
            return false;
        }

        // 일자 체크
        if ($c.stf.compareFromToDate2(edt_FROM_TRNSM_DD, edt_TO_TRNSM_DD) === false) {
            return false;
        }

        // 검색기간 일주일 단위 체크.
        if ($c.utils.cGetDifTodayInputday(edt_FROM_TRNSM_DD.Text, edt_TO_TRNSM_DD.Text) > 6) {
            alert("검색 기간은 일주일 단위로만 가능합니다.");
            return false;
        }
    } else if (pGubun === "ins_Trans") {
        // 조회된 목록이 있는가?
        if (dts_List.getRowCount() === 0) {
            alert("조회된 정보가 없습니다.");
            return false;
        }

        // 체크된 것이 있는지 검사
        let nTrueCnt = 0;
        // TODO Stage2: 0-based 인덱스 검토(비정형 루프 — 토큰만 치환)
        for (let nRow = 1; nRow <= dts_List.getRowCount(); nRow++) {
            if (dts_List.getCellData(nRow, "CHK") === "T") {
                nTrueCnt++;
                break;
            }
        }
        if (nTrueCnt === 0) {
            alert("선택된 정보가 없습니다.");
            return false;
        }
    }
    return true;
};

/**
 * 선택된 row의 값을 강제로 변경.. 이렇게 하면 변경된 row만 서버로 전송될것 같아서..
 */
scwin.setTransData = function() {
    let nRow = dts_List.getRowPosition();
    dts_List.setCellData(nRow, "CHK", "T");
};

scwin.allCheck = function() {
    const checkArray = [ckb_STD_CD_APPL_CONTN_TP_CD_01, ckb_STD_CD_APPL_CONTN_TP_CD_02, ckb_STD_CD_APPL_CONTN_TP_CD_11, ckb_STD_CD_APPL_CONTN_TP_CD_10, ckb_STD_CD_APPL_CONTN_TP_CD_12, ckb_STD_CD_APPL_CONTN_TP_CD_04_05, ckb_STD_CD_APPL_CONTN_TP_CD_06, ckb_STD_CD_APPL_CONTN_TP_CD_08, ckb_STD_CD_APPL_CONTN_TP_CD_07, ckb_STD_CD_APPL_CONTN_TP_CD_03, ckb_STD_CD_APPL_CONTN_TP_CD_09, ckb_STD_CD_APPL_CONTN_TP_CD_13];
    if (ckb_ALL.checked === true) {
        for (let i = 0; i < checkArray.length; i++) {
            checkArray[i].checked = 0;
        }
    }
};
scwin.arrPar = new Array();

/********************************************** 
 * 함수명   : fn_GetParam
 * 설명       : 전달 값을 정의한다.
 ***********************************************/
scwin.getParam = function(arrPar) {
    scwin.arrPar[0] = txb_param1.getValue(); // ISUR_APPL_ID  
    scwin.arrPar[1] = txb_param2.getValue();
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    scwin.arrPar, length;
};

/********************************************** 
 * 함수명   : fn_chkValid
 * 설명       : 이미 수익처리가 완료된건 체크대상을 알아낸다.
 ***********************************************/
scwin.chkClickValid = function(col, colid, bCheck) {
    // alert("col : " + col);
    // alert(" colid: " + colid);
    // alert(" bCheck: " + bCheck);

    if (bCheck === '1') {
        // 체크선택
        if ("Y" === dts_List.getCellData(col, "PAKERNPRC_COMPLT_YN")) {
            alert("이미 수익처리가 완료된건은 전송 할 수 없습니다.");
            dts_List.setCellData(col, "CHK", "0");
            return false;
        }
    }
};

/********************************************** 
 * 함수명   : fn_setCheckBox
 * 설명       : 그리드 체크박스 전체선택 또는 전체선택 해제
 ***********************************************/
scwin.setCheckBox = function(grdObj, dtsObj, bCheck) {
    let vcd = "";
    if (bCheck === '1') {
        vcd = "T";
    } else {
        vcd = "F";
    }
for (let i = 1; i <= dtsObj.CountRow; i++) {
        if (dtsObj.getCellData(i, "PAKERNPRC_OBJ_YN") === 'N') {
            // 수익처리대상여부
            dtsObj.setCellData(i, "CHK", "F");
        } else {
            dtsObj.setCellData(i, "CHK", vcd);
        }
    }
};

scwin.grd_Grid_CanColumnPosChange = function(row, colid) {
    return true;
};

scwin.gform_onload = function() {
    //  기간 from~ to  셋팅	
    const vCurDate = $c.utils.cGetToday("yyyymmdd");
    // edt_SSTD_CD_GRNT_DD.text = cGetMinusDate2(vCurDate, 31);	// 1달 날짜
    edt_SSTD_CD_GRNT_DD.setValue($c.utils.cGetToday("yyyymmdd")); // 현재날짜로 수정

    edt_ESTD_CD_GRNT_DD.setValue($c.utils.cGetToday("yyyymmdd")); // 현재날짜
    // edt_SFEE_DEPO_DD.text = cGetMinusDate2(vCurDate, 31);	// 1달 날짜
    // edt_EFEE_DEPO_DD.text = cGetToday("yyyymmdd");		// 현재날짜

    txb_param1.hide();
    txb_param2.hide();
    ckb_11.hide();
    ckb_7.hide();
    label_19.hide();
    label_7.hide();
    ckb_ALL.setValue(1);
    scwin.allCheck();
};

